// Map each new req to its job-family config and load it from disk.
// Config keys the rubric, the feeder-req list, the recency window, the
// rejection-reason allow/deny lists, and the fit threshold. Halt (do not
// fall back to defaults) if no config exists for the req's job family.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const CONFIG_DIR = $env.CONFIG_DIR || '/data/rediscovery';
const job = $json;

function slugify(s) {
  return String(s || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

// Job family resolves from a `job_family` custom field if present, else the
// first department name. This is the filename the recruiter authored.
const customFamily = (job.custom_fields && (job.custom_fields.job_family || job.custom_fields.Job_Family)) || '';
const deptName = (job.departments && job.departments[0] && job.departments[0].name) || '';
const family = slugify(customFamily) || slugify(deptName);

if (!family) {
  return [{ json: { status: 'halted', reason: 'no_job_family', job_id: job.id, job_name: job.name } }];
}

const configPath = path.join(CONFIG_DIR, `${family}.json`);
if (!fs.existsSync(configPath)) {
  return [{ json: { status: 'halted', reason: 'missing_config', job_family: family, expected_path: configPath } }];
}

const raw = fs.readFileSync(configPath, 'utf8');
const cfg = JSON.parse(raw);
const configSha = crypto.createHash('sha256').update(raw).digest('hex').slice(0, 16);

const recencyMonths = Number(cfg.recency_months) || 18;
const recencyCutoffIso = new Date(Date.now() - recencyMonths * 30 * 24 * 3600000).toISOString();

return [{
  json: {
    status: 'config_loaded',
    req_id: job.id,
    req_title: job.name,
    req_url: `https://app.greenhouse.io/sdash/${job.id}`,
    job_family: family,
    config_sha: configSha,
    recency_months: recencyMonths,
    recency_cutoff_iso: recencyCutoffIso,
    match_job_ids: cfg.match_job_ids || [],
    min_stage_reached: cfg.min_stage_reached || [],
    rejection_reasons_allow: cfg.rejection_reasons_allow || [],
    rejection_reasons_deny: cfg.rejection_reasons_deny || [],
    do_not_contact_tags: cfg.do_not_contact_tags || ['do-not-contact', 'gdpr-erased', 'opted-out'],
    fit_threshold: Number(cfg.fit_threshold) || 4,
    top_n: Number(cfg.top_n) || 10,
    rubric: cfg.rubric || {},
  }
}];

// Deterministic eligibility filter. Runs once per rejected application.
// Keeps an application only if it is a genuine silver medalist for THIS req:
// - applied to one of the configured feeder reqs (match_job_ids)
// - reached a late stage (min_stage_reached)
// - rejection reason is in the allow-list AND not in the deny-list
// - last activity within the recency window
// - candidate carries no do-not-contact / erasure / opt-out tag
// Drops everything else silently. No LLM has seen the record yet.
const app = $json;
const cfg = $('Load Match Config').item.json;

function drop(reason) { return []; }

// 1) Feeder-req match: the candidate must have applied to a configured past req.
const appJobIds = (app.jobs || []).map((j) => j.id);
const isFeeder = appJobIds.some((id) => cfg.match_job_ids.includes(id));
if (!isFeeder) return drop('not_a_feeder_req');

// 2) Late-stage gate: silver medalists reached a configured late stage.
const stage = (app.current_stage && app.current_stage.name) || '';
if (cfg.min_stage_reached.length && !cfg.min_stage_reached.includes(stage)) {
  return drop('did_not_reach_late_stage');
}

// 3) Rejection-reason gates. Deny wins over allow.
const reason = (app.rejection_reason && app.rejection_reason.name) || '';
if (cfg.rejection_reasons_deny.includes(reason)) return drop('disqualifying_rejection_reason');
if (cfg.rejection_reasons_allow.length && !cfg.rejection_reasons_allow.includes(reason)) {
  return drop('rejection_reason_not_in_allow_list');
}

// 4) Recency: last activity must be within the window.
const lastActivity = app.last_activity_at || app.last_activity || null;
if (lastActivity && new Date(lastActivity) < new Date(cfg.recency_cutoff_iso)) {
  return drop('outside_recency_window');
}

// 5) Consent / suppression tags on the candidate.
const tags = (app.candidate_tags || (app.candidate && app.candidate.tags) || []).map((t) => String(t).toLowerCase());
if (cfg.do_not_contact_tags.some((t) => tags.includes(String(t).toLowerCase()))) {
  return drop('suppressed_do_not_contact');
}

const candidateId = app.candidate_id || (app.candidate && app.candidate.id);

return [{
  json: {
    status: 'eligible',
    req_id: cfg.req_id,
    req_title: cfg.req_title,
    req_url: cfg.req_url,
    job_family: cfg.job_family,
    config_sha: cfg.config_sha,
    fit_threshold: cfg.fit_threshold,
    top_n: cfg.top_n,
    rubric: cfg.rubric,
    candidate_id: candidateId,
    application_id: app.id,
    prior_stage_reached: stage,
    prior_rejection_reason: reason,
    prior_req_ids: appJobIds,
    last_activity_at: lastActivity,
  }
}];

