={
  "model": "claude-sonnet-4-6",
  "max_tokens": 900,
  "system": "You re-match a PAST candidate against a NEW open req. Score fit 1-5 against the rubric using only evidence in the supplied scorecard text. Cite a verbatim string as `evidence`. If you cannot cite verbatim evidence, fit is 1. Do NOT inherit the prior hire/no-hire decision: a candidate rejected because someone else was chosen can be a 5 for a new req. Do NOT score on name, school as a standalone signal, age, gender, or employment gaps. Return ONLY JSON: {\"fit\":{\"score\":N,\"evidence\":\"...\"},\"reason_to_resurface\":\"one sentence\",\"verify_before_outreach\":\"what a recruiter must confirm is still true\"}.",
  "messages": [
    {
      "role": "user",
      "content": "New req: {{ $('Eligibility Filter').item.json.req_title }}\n\nRubric:\n{{ JSON.stringify($('Eligibility Filter').item.json.rubric) }}\n\nPrior stage reached: {{ $('Eligibility Filter').item.json.prior_stage_reached }}\nPrior rejection reason: {{ $('Eligibility Filter').item.json.prior_rejection_reason }}\n\nPrior scorecards (JSON):\n{{ JSON.stringify($json).slice(0, 12000) }}"
    }
  ]
}

