// Parse Claude's JSON, enforce the evidence rule, decide keep vs drop.
const input = $json;
const ctx = $('Eligibility Filter').item.json;

let parsed;
try {
  const text = (input.content && input.content[0] && input.content[0].text) || '';
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('no JSON object in response');
  parsed = JSON.parse(m[0]);
} catch (e) {
  return [{ json: { status: 'scored', keep: false, error: 'unparseable_score', req_id: ctx.req_id, candidate_id: ctx.candidate_id } }];
}

const rawScore = Number(parsed.fit && parsed.fit.score) || 1;
const evidence = (parsed.fit && parsed.fit.evidence) || '';
const fit = (rawScore > 1 && evidence.trim().length > 0) ? Math.min(5, Math.max(1, rawScore)) : 1;
const keep = fit >= ctx.fit_threshold;

return [{
  json: {
    status: 'scored',
    keep,
    req_id: ctx.req_id,
    req_title: ctx.req_title,
    req_url: ctx.req_url,
    job_family: ctx.job_family,
    config_sha: ctx.config_sha,
    top_n: ctx.top_n,
    candidate_id: ctx.candidate_id,
    application_id: ctx.application_id,
    prior_stage_reached: ctx.prior_stage_reached,
    prior_rejection_reason: ctx.prior_rejection_reason,
    fit,
    evidence: evidence.slice(0, 240),
    reason_to_resurface: (parsed.reason_to_resurface || '').slice(0, 240),
    verify_before_outreach: (parsed.verify_before_outreach || '').slice(0, 240),
    scored_at: new Date().toISOString(),
  }
}];

// Append one audit line per scored candidate. Pseudonymous: candidate_id +
// the Greenhouse link only, no name / no scorecard text. This is the record
// that a past candidate was machine-scored for re-contact consideration.
const fs = require('fs');
const path = require('path');

const AUDIT_DIR = $env.AUDIT_DIR || '/data/audit';
fs.mkdirSync(AUDIT_DIR, { recursive: true });

const input = $json;
const yyyymm = new Date().toISOString().slice(0, 7);
const auditPath = path.join(AUDIT_DIR, `rediscovery-${yyyymm}.jsonl`);

const entry = {
  ts: new Date().toISOString(),
  req_id: input.req_id,
  job_family: input.job_family,
  config_sha: input.config_sha,
  candidate_id: input.candidate_id,
  application_id: input.application_id,
  prior_stage_reached: input.prior_stage_reached,
  prior_rejection_reason: input.prior_rejection_reason,
  fit: input.fit,
  kept: !!input.keep,
  model: 'claude-sonnet-4-6',
};

fs.appendFileSync(auditPath, JSON.stringify(entry) + '\n', 'utf8');
return [{ json: input }];

// Aggregate all scored candidates, group by req, dedupe by candidate (keep
// the highest fit), keep the top_n above threshold, and build one Slack
// digest payload per req. Emits one item per req for the Slack node.
const all = $input.all().map((i) => i.json).filter((j) => j && j.keep);

const byReq = {};
for (const r of all) {
  byReq[r.req_id] = byReq[r.req_id] || { req: r, candidates: {} };
  const existing = byReq[r.req_id].candidates[r.candidate_id];
  if (!existing || r.fit > existing.fit) {
    byReq[r.req_id].candidates[r.candidate_id] = r;
  }
}

const out = [];
for (const reqId of Object.keys(byReq)) {
  const group = byReq[reqId];
  const ranked = Object.values(group.candidates).sort((a, b) => b.fit - a.fit).slice(0, group.req.top_n);
  if (!ranked.length) continue;

  const lines = ranked.map((c, idx) =>
    `*${idx + 1}. fit ${c.fit}/5* — <https://app.greenhouse.io/people/${c.candidate_id}|candidate ${c.candidate_id}>\n   _Reached:_ ${c.prior_stage_reached} · _Rejected:_ ${c.prior_rejection_reason}\n   _Why:_ ${c.reason_to_resurface}\n   _Confirm first:_ ${c.verify_before_outreach}`
  ).join('\n\n');

  out.push({
    json: {
      req_id: group.req.req_id,
      req_title: group.req.req_title,
      req_url: group.req.req_url,
      config_sha: group.req.config_sha,
      shortlist_count: ranked.length,
      slack_text: `*Silver-medalist shortlist — ${group.req.req_title}*\n${ranked.length} past candidate(s) re-matched. The recruiter decides outreach — nothing has been contacted or moved.\n\n${lines}\n\n_Matching rules: config \`${group.req.config_sha}\`. <${group.req.req_url}|Open the req>_`,
    }
  });
}

return out;
